package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.graphics.Typeface;
import android.view.View;
import android.widget.*;
import org.json.*;
/** Game cards scoped by server-side friend/block permissions; no arbitrary media posts. */
final class GameFeedView extends ScrollView {
 interface Source {void request(String action,JSONObject data,AccountRepository.Callback callback);}
 private final Source source;private final AccountRepository repo;private final LinearLayout body,list;private final TextView state;private final Button refresh,more;private final String owner;private JSONObject cursor=new JSONObject();private final java.util.Set<String> seen=new java.util.HashSet<>();private boolean loading,detached;private int generation;
 GameFeedView(Context c){this(c,new AccountRepository(c)::gameFeed);}
 GameFeedView(Context c,Source gateway){super(c);source=gateway;repo=new AccountRepository(c);owner=SessionPreferences.get(c).getString("user_id","");setFillViewport(true);setVerticalScrollBarEnabled(false);body=new LinearLayout(c);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(16),dp(18),dp(16),dp(24));addView(body);body.addView(NativeSheet.text(c,"ENTRE AMIGOS",11,NativeTheme.accent(c)));TextView title=NativeSheet.text(c,"Feed dos amigos",27,0xfff3f1fc);title.setTypeface(null,Typeface.BOLD);body.addView(title);Button share=button("Compartilhar jogo",true);body.addView(share);share.setOnClickListener(v->compose());refresh=button("Atualizar",false);body.addView(refresh);refresh.setOnClickListener(v->load(true));list=new LinearLayout(c);list.setOrientation(LinearLayout.VERTICAL);body.addView(list);state=NativeSheet.text(c,"",13,0xffc9badc);body.addView(state);more=button("Carregar mais",false);body.addView(more);more.setOnClickListener(v->load(false));load(true);}
 private boolean current(){return !detached&&owner.equals(SessionPreferences.get(getContext()).getString("user_id",""));}
 @Override protected void onDetachedFromWindow(){detached=true;generation++;super.onDetachedFromWindow();}
 private void load(boolean reset){if(loading||!current())return;loading=true;refresh.setEnabled(false);more.setEnabled(false);state.setText("Carregando atividades…");if(reset){cursor=new JSONObject();seen.clear();list.removeAllViews();}int ticket=++generation;source.request("list",cursor,(rows,error)->{if(!current()||ticket!=generation)return;loading=false;refresh.setEnabled(true);more.setEnabled(true);if(error!=null){state.setText(error);more.setVisibility(VISIBLE);more.setText("Tentar novamente");return;}for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row!=null&&seen.add(row.optString("id")))render(row);}if(rows.length()>0){JSONObject last=rows.optJSONObject(rows.length()-1);cursor=data("before_id",last.optString("id"));put(cursor,"before_time",last.optString("created_at"));}more.setText("Carregar mais");more.setVisibility(rows.length()==20?VISIBLE:GONE);state.setText(seen.isEmpty()?"Nenhuma atividade no feed.":"");});}
 private void render(JSONObject row){Context c=getContext();JSONObject title=row.optJSONObject("title");if(title==null)return;LinearLayout tile=card();list.addView(tile);LinearLayout person=new LinearLayout(c);person.setGravity(android.view.Gravity.CENTER_VERTICAL);ImageView avatar=new ImageView(c);avatar.setImageResource(R.drawable.app_logo);avatar.setScaleType(ImageView.ScaleType.CENTER_CROP);avatar.setBackground(AppStyle.shape(avatar,NativeTheme.panelDark(c),22));avatar.setClipToOutline(true);person.addView(avatar,new LinearLayout.LayoutParams(dp(40),dp(40)));JSONObject author=row.optJSONObject("author");if(author!=null)AccountImageLoader.load(avatar,author.optString("avatar_url"));LinearLayout who=new LinearLayout(c);who.setOrientation(LinearLayout.VERTICAL);who.setPadding(dp(10),0,0,0);who.addView(NativeSheet.text(c,author==null?"Amigo":author.optString("nome","Amigo"),14,0xfff0ebf8));who.addView(NativeSheet.text(c,MessageTime.day(row.optString("created_at"))+" • "+MessageTime.time(row.optString("created_at")),11,0xffa69bb6));person.addView(who,new LinearLayout.LayoutParams(0,-2,1));tile.addView(person);tile.addView(NativeSheet.text(c,GameFeedModel.action(row),15,0xffdcd0f4));ImageView cover=new ImageView(c);cover.setImageResource(R.drawable.app_logo);cover.setScaleType(ImageView.ScaleType.FIT_CENTER);cover.setBackground(AppStyle.shape(cover,NativeTheme.panelDark(c),14));cover.setClipToOutline(true);cover.setContentDescription("Ver detalhes de "+title.optString("nome"));cover.setFocusable(true);tile.addView(cover,new LinearLayout.LayoutParams(-1,dp(170)));MobileArtworkLoader.load(cover,title,false,true);TextView name=NativeSheet.text(c,title.optString("nome"),21,0xfff3f0fa);name.setTypeface(null,Typeface.BOLD);tile.addView(name);tile.addView(NativeSheet.text(c,title.optString("plataforma")+(title.optInt("ano")>0?" • "+title.optInt("ano"):""),12,0xffb1a3c3));Button details=button("Ver detalhes",false);tile.addView(details);Runnable open=()->{try{JSONObject clean=GameFeedModel.title(title);put(clean,"_readonly",true);put(clean,"status","Compartilhado por um amigo");NativeSheet sheet=TitleDetailsDialog.show(c,clean,false,(x,d)->{});if(sheet!=null){Button add=button("Adicionar à minha biblioteca",true);sheet.footer.setVisibility(VISIBLE);sheet.footer.addView(add);add.setOnClickListener(v->{sheet.dialog.dismiss();add(title);});}}catch(JSONException e){state.setText("Não foi possível abrir este jogo.");}};cover.setOnClickListener(v->open.run());details.setOnClickListener(v->open.run());Button like=button("",false);tile.addView(like);paintLike(like,row);like.setOnClickListener(v->{like.setEnabled(false);JSONObject input=data("id",row.optString("id"));put(input,"liked",!row.optBoolean("liked"));source.request("like",input,(result,error)->{if(!current()||!tile.isAttachedToWindow())return;like.setEnabled(true);if(error!=null){state.setText(error);return;}JSONObject changed=result.optJSONObject(0);if(changed!=null){put(row,"liked",changed.optBoolean("liked"));put(row,"like_count",changed.optInt("like_count"));paintLike(like,row);}});});Button add=button("Adicionar à biblioteca",false);tile.addView(add);add.setOnClickListener(v->add(title));if(owner.equals(row.optString("user_id"))&&GameFeedModel.manual(row)){Button remove=button("Excluir publicação",false);tile.addView(remove);remove.setOnClickListener(v->{NativeSheet confirm=new NativeSheet(c,"Excluir publicação?");confirm.body.addView(NativeSheet.text(c,"A publicação e suas curtidas serão removidas do feed.",14,0xffc8b8d8));Button yes=button("Excluir",true);confirm.body.addView(yes);yes.setOnClickListener(x->{yes.setEnabled(false);source.request("delete",data("id",row.optString("id")),(r,e)->{if(!current())return;if(e!=null){state.setText(e);yes.setEnabled(true);return;}confirm.dialog.dismiss();list.removeView(tile);});});confirm.show();});}}
 private void paintLike(Button like,JSONObject row){boolean liked=row.optBoolean("liked");like.setText((liked?"Curtido":"Curtir")+" • "+Math.max(0,row.optInt("like_count")));like.setSelected(liked);like.setContentDescription(like.getText()+(liked?", ativado":""));AppStyle.icon(like,ActionIcon.HEART,liked?0xffff8bac:0xffc7b2f5);}
 private void add(JSONObject title){try{new CatalogAddDialog(getContext(),false,0,GameFeedModel.title(title),()->android.widget.Toast.makeText(getContext(),"Jogo salvo na sua biblioteca",Toast.LENGTH_SHORT).show());}catch(JSONException e){state.setText("Não foi possível preparar este jogo.");}}
 private void compose(){Context c=getContext();NativeSheet sheet=new NativeSheet(c,"Compartilhar um jogo");sheet.body.addView(NativeSheet.text(c,"Visível apenas para amigos.",14,0xffc7b7d6));EditText search=NativeSheet.input(c,"Buscar jogo",120);sheet.body.addView(search);Spinner action=NativeSheet.options(c,new String[]{"Recomendo este jogo","Comecei a jogar","Zerei"});sheet.body.addView(action);LinearLayout choices=new LinearLayout(c);choices.setOrientation(LinearLayout.VERTICAL);sheet.body.addView(choices);TextView feedback=NativeSheet.text(c,"Carregando sua biblioteca…",13,0xffc8b1ef);sheet.body.addView(feedback);Button submit=button("Compartilhar com amigos",true);submit.setEnabled(false);sheet.body.addView(submit);sheet.show();String[] selected={""};java.util.List<JSONObject> games=new java.util.ArrayList<>();Runnable draw=()->{choices.removeAllViews();String query=search.getText().toString().toLowerCase(java.util.Locale.ROOT);int count=0;for(JSONObject game:games){if(!game.optString("nome").toLowerCase(java.util.Locale.ROOT).contains(query))continue;if(++count>40)continue;Button pick=button(game.optString("nome"),false);pick.setSelected(game.optString("id").equals(selected[0]));pick.setContentDescription(game.optString("nome")+(pick.isSelected()?", selecionado":""));choices.addView(pick);pick.setOnClickListener(v->{selected[0]=game.optString("id");submit.setEnabled(true);for(int i=0;i<choices.getChildCount();i++){View other=choices.getChildAt(i);other.setSelected(other==pick);other.setAlpha(other==pick?1f:.65f);}feedback.setText("Selecionado: "+game.optString("nome"));});}feedback.setText(games.isEmpty()?"Nenhum jogo na biblioteca.":count>40?"Mostrando 40 jogos. Refine a busca.":selected[0].isEmpty()?"Nenhum jogo selecionado.":"Jogo selecionado.");};search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int n,int x){}public void onTextChanged(CharSequence s,int a,int b,int n){draw.run();}public void afterTextChanged(android.text.Editable e){}});repo.profileLibrary((rows,error)->{if(!current()||!sheet.dialog.isShowing())return;if(error!=null){feedback.setText(error);return;}for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);if(r!=null&&"jogos".equals(r.optString("categoria")))games.add(r);}draw.run();});submit.setOnClickListener(v->{if(!current()||selected[0].isEmpty())return;sheet.busy(true);submit.setEnabled(false);feedback.setText("Compartilhando…");JSONObject input=data("item_id",selected[0]);put(input,"action",new String[]{"recommend","started","finished"}[action.getSelectedItemPosition()]);source.request("share",input,(r,e)->{if(!current())return;sheet.busy(false);if(e!=null){feedback.setText(e);submit.setEnabled(true);return;}sheet.dialog.dismiss();load(true);});});}
 private Button button(String text,boolean primary){Button b=new Button(getContext());b.setText(text);AppStyle.button(b,primary);return b;}
 private LinearLayout card(){LinearLayout x=new LinearLayout(getContext());x.setOrientation(LinearLayout.VERTICAL);x.setPadding(dp(16),dp(16),dp(16),dp(16));x.setBackground(AppStyle.surface(x,NativeTheme.panel(getContext()),20));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(16),0,0);x.setLayoutParams(p);return x;}
 private int dp(int n){return AppStyle.dp(this,n);}private static JSONObject data(String key,Object value){return put(new JSONObject(),key,value);}private static JSONObject put(JSONObject o,String key,Object value){try{o.put(key,value);}catch(JSONException ignored){}return o;}
}
